/// <reference types="@stdlib/types"/>

import { ComplexLike } from '@stdlib/types/complex';
import zeros = require( '@stdlib/ndarray/zeros' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import MultiSlice = require( '@stdlib/slice/multi' );
import fillSliceBy = require( './index' );

/**
* Real-valued callback function.
*
* @returns fill value
*/
function fcn1(): number {
	return 10.0;
}

/**
* Complex-valued callback function.
*
* @returns fill value
*/
function fcn2(): ComplexLike {
	return new Complex128( 10.0, 10.0 );
}


// TESTS //

// The function returns an ndarray...
{
	const s = new MultiSlice( null, null );

	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), s, fcn1 ); // $ExpectType float64ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), s, fcn2 ); // $ExpectType complex128ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), s, fcn1 ); // $ExpectType genericndarray<number>

	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), s, {}, fcn1 ); // $ExpectType float64ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), s, {}, fcn2 ); // $ExpectType complex128ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), s, {}, fcn1 ); // $ExpectType genericndarray<number>

	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), s, fcn1, {} ); // $ExpectType float64ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), s, fcn2, {} ); // $ExpectType complex128ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), s, fcn1, {} ); // $ExpectType genericndarray<number>

	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), s, {}, fcn1, {} ); // $ExpectType float64ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), s, {}, fcn2, {} ); // $ExpectType complex128ndarray
	fillSliceBy( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), s, {}, fcn1, {} ); // $ExpectType genericndarray<number>
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray-like object...
{
	const s = new MultiSlice( null, null );

	fillSliceBy( '5', s, fcn1 ); // $ExpectError
	fillSliceBy( 5, s, fcn1 ); // $ExpectError
	fillSliceBy( true, s, fcn1 ); // $ExpectError
	fillSliceBy( false, s, fcn1 ); // $ExpectError
	fillSliceBy( null, s, fcn1 ); // $ExpectError
	fillSliceBy( undefined, s, fcn1 ); // $ExpectError
	fillSliceBy( {}, s, fcn1 ); // $ExpectError
	fillSliceBy( [ 1 ], s, fcn1 ); // $ExpectError
	fillSliceBy( ( x: number ): number => x, s, fcn1 ); // $ExpectError

	fillSliceBy( '5', s, {}, fcn1 ); // $ExpectError
	fillSliceBy( 5, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( true, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( false, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( null, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( undefined, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( {}, s, {}, fcn1 ); // $ExpectError
	fillSliceBy( [ 1 ], s, {}, fcn1 ); // $ExpectError
	fillSliceBy( ( x: number ): number => x, s, {}, fcn1 ); // $ExpectError

	fillSliceBy( '5', s, fcn1, {} ); // $ExpectError
	fillSliceBy( 5, s, fcn1, {} ); // $ExpectError
	fillSliceBy( true, s, fcn1, {} ); // $ExpectError
	fillSliceBy( false, s, fcn1, {} ); // $ExpectError
	fillSliceBy( null, s, fcn1, {} ); // $ExpectError
	fillSliceBy( undefined, s, fcn1, {} ); // $ExpectError
	fillSliceBy( {}, s, fcn1, {} ); // $ExpectError
	fillSliceBy( [ 1 ], s, fcn1, {} ); // $ExpectError
	fillSliceBy( ( x: number ): number => x, s, fcn1, {} ); // $ExpectError

	fillSliceBy( '5', s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( 5, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( true, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( false, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( null, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( undefined, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( {}, s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( [ 1 ], s, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( ( x: number ): number => x, s, {}, fcn1, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid slice argument...
{
	const x = zeros( [ 2, 2 ] );

	fillSliceBy( x, '5', fcn1 ); // $ExpectError
	fillSliceBy( x, false, fcn1 ); // $ExpectError
	fillSliceBy( x, true, fcn1 ); // $ExpectError
	fillSliceBy( x, [ '5' ], fcn1 ); // $ExpectError
	fillSliceBy( x, ( x: number ): number => x, fcn1 ); // $ExpectError

	fillSliceBy( x, '5', {}, fcn1 ); // $ExpectError
	fillSliceBy( x, false, {}, fcn1 ); // $ExpectError
	fillSliceBy( x, true, {}, fcn1 ); // $ExpectError
	fillSliceBy( x, [ '5' ], {}, fcn1 ); // $ExpectError
	fillSliceBy( x, ( x: number ): number => x, {}, fcn1 ); // $ExpectError

	fillSliceBy( x, '5', fcn1, {} ); // $ExpectError
	fillSliceBy( x, false, fcn1, {} ); // $ExpectError
	fillSliceBy( x, true, fcn1, {} ); // $ExpectError
	fillSliceBy( x, [ '5' ], fcn1, {} ); // $ExpectError
	fillSliceBy( x, ( x: number ): number => x, fcn1, {} ); // $ExpectError

	fillSliceBy( x, '5', {}, fcn1, {} ); // $ExpectError
	fillSliceBy( x, false, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( x, true, {}, fcn1, {} ); // $ExpectError
	fillSliceBy( x, [ '5' ], {}, fcn1, {} ); // $ExpectError
	fillSliceBy( x, ( x: number ): number => x, {}, fcn1, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( [ 2, 2 ] );
	const s = new MultiSlice( null, null );

	fillSliceBy( x, s, '5', fcn1 ); // $ExpectError
	fillSliceBy( x, s, 5, fcn1 ); // $ExpectError
	fillSliceBy( x, s, null, fcn1 ); // $ExpectError
	fillSliceBy( x, s, true, fcn1 ); // $ExpectError
	fillSliceBy( x, s, false, fcn1 ); // $ExpectError
	fillSliceBy( x, s, [ '5' ], fcn1 ); // $ExpectError
	fillSliceBy( x, s, ( x: number ): number => x, fcn1 ); // $ExpectError

	fillSliceBy( x, s, '5', fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, 5, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, null, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, true, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, false, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, [ '5' ], fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, ( x: number ): number => x, fcn1, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a `strict` option which is not a boolean...
{
	const x = zeros( [ 2, 2 ] );
	const s = new MultiSlice( null, null );

	fillSliceBy( x, s, { 'strict': '5' }, fcn1 ); // $ExpectError
	fillSliceBy( x, s, { 'strict': 5 }, fcn1 ); // $ExpectError
	fillSliceBy( x, s, { 'strict': null }, fcn1 ); // $ExpectError
	fillSliceBy( x, s, { 'strict': [ '5' ] }, fcn1 ); // $ExpectError
	fillSliceBy( x, s, { 'strict': {} }, fcn1 ); // $ExpectError
	fillSliceBy( x, s, { 'strict': ( x: number ): number => x }, fcn1 ); // $ExpectError

	fillSliceBy( x, s, { 'strict': '5' }, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, { 'strict': 5 }, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, { 'strict': null }, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, { 'strict': [ '5' ] }, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, { 'strict': {} }, fcn1, {} ); // $ExpectError
	fillSliceBy( x, s, { 'strict': ( x: number ): number => x }, fcn1, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a callback argument which is not a function...
{
	const x = zeros( [ 2, 2 ] );
	const s = new MultiSlice( null, null );

	fillSliceBy( x, s, '5' ); // $ExpectError
	fillSliceBy( x, s, 5 ); // $ExpectError
	fillSliceBy( x, s, true ); // $ExpectError
	fillSliceBy( x, s, false ); // $ExpectError
	fillSliceBy( x, s, null ); // $ExpectError
	fillSliceBy( x, s, undefined ); // $ExpectError
	fillSliceBy( x, s, {} ); // $ExpectError
	fillSliceBy( x, s, [ 1 ] ); // $ExpectError

	fillSliceBy( x, s, {}, '5' ); // $ExpectError
	fillSliceBy( x, s, {}, 5 ); // $ExpectError
	fillSliceBy( x, s, {}, true ); // $ExpectError
	fillSliceBy( x, s, {}, false ); // $ExpectError
	fillSliceBy( x, s, {}, null ); // $ExpectError
	fillSliceBy( x, s, {}, undefined ); // $ExpectError
	fillSliceBy( x, s, {}, {} ); // $ExpectError
	fillSliceBy( x, s, {}, [ 1 ] ); // $ExpectError

	fillSliceBy( x, s, {}, '5', {} ); // $ExpectError
	fillSliceBy( x, s, {}, 5, {} ); // $ExpectError
	fillSliceBy( x, s, {}, true, {} ); // $ExpectError
	fillSliceBy( x, s, {}, false, {} ); // $ExpectError
	fillSliceBy( x, s, {}, {} ); // $ExpectError
	fillSliceBy( x, s, {}, undefined, {} ); // $ExpectError
	fillSliceBy( x, s, {}, {}, {} ); // $ExpectError
	fillSliceBy( x, s, {}, [ 1 ], {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	fillSliceBy(); // $ExpectError
}
